entries[188283] = { ["name"] = "Blutsturz", ["text"] = "Nahkampfreichweite\nSofort 5 sek. Abklingzeit\nVerursacht 12 Sek. lang alle 3 Sek. 2386 körperlichen Schaden und erhöht währenddessen den vom Opfer erlittenen körperlichen Schaden um 10%." }
entries[188284] = { ["name"] = "Schockwelle", ["text"] = "Sofort\nDer Zaubernde stößt eine Energiewelle nach vorn aus, die Schaden verursacht und alle gegnerischen Ziele innerhalb von 10 Metern kurzzeitig betäubt." }
