entries[188289] = { ["name"] = "Prinz Arthas Menethil", ["text"] = "Sofort\n'Arkane Geschosse' hat eine Chance von 35%, eine Zeitanomalie zu öffnen, die einen zufälligen Helden der Vergangenheit herbeiruft, der Euch 10 Sek. lang im Kampf unterstützt." }
entries[188290] = { ["name"] = "Tod und Verfall", ["text"] = "Unbegrenzte Reichweite\nSofort\nVerdirbt den anvisierten Boden und fügt Zielen in diesem Bereich im Verlauf von 10 Sek. [(3.6036% der Angriffskraft) * 11] Schattenschaden zu.\n\nBlut, Unheilig\nSolange Ihr Euch im Effektbereich aufhaltet, trifft ['Nekrotischer Stoß' und] [ Blut : 'Herzstoß' bis zu 0 zusätzliche Ziele ]['Geißelstoß' trifft bis zu 7 Gegner in der Nähe des Ziels.]" }
entries[188291] = { ["name"] = "Astrales Zustoßen", ["text"] = "Nahkampfreichweite\nSofort\nGreift sofort mit beiden Waffen an und verursacht Frostschaden." }
entries[188292] = { ["name"] = "Eisiger Griff", ["text"] = "10 Meter Reichweite\nWirken in 1 sek. 3 sek. Abklingzeit\nDer Zaubernde greift mit einer eisigen Hand nach dem Ziel und fügt ihm Frostschaden zu. Zusätzlich werden Bewegungsgeschwindigkeit und Tempo des Ziels um 30% verringert." }
entries[188293] = { ["name"] = "Verstärkte Feuerbombe", ["text"] = "Sofort\nDiese verstärkte Feuerbombe explodiert, wenn sie nicht innerhalb von 1.3 Min. beseitigt wird, und fügt dann allen Gegnern 17043 Feuerschaden zu. Außerdem erhöht die Explosion den durch weitere Feuerbomben erlittenen Schaden 30 Sek. lang um 50%. Dieser Effekt ist stapelbar." }
