entries[188659] = { ["name"] = "Anhängerin: Allari die Seelenfresserin", ["text"] = "Sofort\nAllari beherrscht schon seit Langem den Umgang mit den Kristallen, mit denen die Blutelfen Teufelsenergien einfangen und manipulieren. Sie nutzt die Seelensense, um das Dämonische auf undenkbare Weisen zu ernten. Die Informationen und die Macht, die sie erhalten hat, haben sich schon in zahlreichen Schlachten gegen die Legion als entscheidend erwiesen. Enttäuscht vom mangelnden Fortschritt der Illidari, den Strom an Dämonen aufzuhalten, sucht sie nun jemand Neuen, dem sie folgen und mit ihren Mächten gebührend unterstützen kann." }
